    private void pointer(long down,int action,float... xy){pointerEvent(down,action,true,35,xy);}
    private void pointerEvent(long down,int action,boolean sync,int delay,float... xy){
        int count=xy.length/2;MotionEvent.PointerProperties[] properties=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[count];
        for(int i=0;i<count;i++){properties[i]=new MotionEvent.PointerProperties();properties[i].id=i;properties[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=xy[i*2];coords[i].y=xy[i*2+1];coords[i].pressure=1;coords[i].size=1;}
        MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,count,properties,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);if(!getUiAutomation().injectInputEvent(e,sync))throw new AssertionError("pointer injection rejected");e.recycle();if(delay>0)SystemClock.sleep(delay);
    }
    private void twoFinger(float cx,float cy,float from,float to,float degrees){
        long down=SystemClock.uptimeMillis();pointer(down,MotionEvent.ACTION_DOWN,cx-from,cy);pointer(down,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),cx-from,cy,cx+from,cy);
        float x=from,y=0;for(int i=1;i<=12;i++){float t=i/12f,r=from+(to-from)*t,angle=(float)Math.toRadians(degrees*t);x=(float)Math.cos(angle)*r;y=(float)Math.sin(angle)*r;pointer(down,MotionEvent.ACTION_MOVE,cx-x,cy-y,cx+x,cy+y);}
        pointer(down,MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),cx-x,cy-y,cx+x,cy+y);pointer(down,MotionEvent.ACTION_UP,cx-x,cy-y);settle();
    }
