        ui(()->{for(int side=0;side<start.factions.length;side++)if(side!=start.player&&start.alive(side)&&start.strategy.factionRelation(start.player,side)>=0&&start.campaign.treaty(start.player,side)==null){game.sanguo.api.DiplomacyPreview p=activity.previewDiplomacy(new game.sanguo.api.DiplomacyCommand(activity.deploymentState(),cityId,leader,side,"GOODWILL",0));if(p.allowed()&&p.forecast.oneWayTurns<travel[0]){destination[0]=side;travel[0]=p.forecast.oneWayTurns;}}});
        check(destination[0]>=0&&travel[0]<=2,"normal campaign offers short goodwill route from authority preview: "+travel[0]+" turns");int side=destination[0];game.sanguo.api.DiplomacyPreview goodwill=issueDiplomacy(cityId,side,"GOODWILL",0,leader,"01-goodwill");
