            World w=SessionProbe.view(activity);int envoy=w.idle(w.city(cityId)).stream().max(Comparator.comparingInt(o->o.politics)).get().id;
            game.sanguo.api.DiplomacyPreview treaty=issueDiplomacy(cityId,side,"ALLIANCE",6,envoy,"03-alliance-"+attempt);
